  const cs=document.createElement('div');cs.id='m1Cs';cs.hidden=true;cs.innerHTML='<div class="m1lb m1lt"></div><div class="m1lb m1lbb"></div><div class="tk"><img alt=""><div><b></b><p></p><small>TAP TO CONTINUE</small></div></div><button id="m1Skip">SKIP ▸▸</button>';document.body.appendChild(cs);
