function M1_tw(){const w=$('#tW');if(!w)return;const show=state==='roam'&&TOUCH.on&&!$('#touch').hidden&&(M1_wpn()||!!M1.inv)&&!M1.cs;w.style.display=show?'grid':'none';if(!show)return;const L=['#tB','#tD','#tN','#tF','#tG'].map(s=>$(s)).filter(e=>e&&e.offsetParent!==null).map(e=>e.getBoundingClientRect()).filter(r=>r.width>4);if(!L.length)return;
  const top=Math.min(...L.map(r=>r.top)),right=Math.max(...L.map(r=>r.right)),sz=Math.round(clamp(Math.min(innerWidth,innerHeight)*.15,48,64));w.style.width=w.style.height=sz+'px';w.style.left=Math.round(right-sz-6)+'px';w.style.top=Math.round(Math.max(56,top-sz-14))+'px';w.style.right='auto';w.style.bottom='auto';
  if(M1.inv){w.style.backgroundImage=M1.inv==='ghost'?'none':`url(${itemIcon(M1.inv==='mines'?'mines':'missile')})`;w.textContent=M1.inv==='ghost'?'👻':''}else{w.style.backgroundImage='none';w.textContent='ITEM'}w.classList.toggle('dim',!M1.inv)}
