function M1_scene(D){if(M1.noScene){if(D.end)D.end();return}M1_ui();if(M1.cs)M1_csEnd();M1.cs={D,i:-1,t:0,lt:0,cam:null};BG23_cut();RO.frozen=true;RO.v=0;document.body.classList.add('m1cs');$('#m1Cs').hidden=false;$('#npcSay').hidden=true;if(D.start)D.start();M1_csNext();camSnap=true}
function M1_csNext(){const C=M1.cs;if(!C)return;C.i++;C.lt=0;const L=C.D.lines;if(C.i>=L.length)return M1_csEnd();const[w,txt]=L[C.i],el=$('#m1Cs');el.querySelector('img').src=M1_av(w);el.querySelector('b').textContent=(M1_WHO[w]||{n:w}).n;el.querySelector('p').innerHTML=txt;el.querySelector('.tk').style.borderColor=(M1_WHO[w]||{}).col||'#ffd400';M1_snd('pick')}
