function M1_spawn(S,kind,n,at,r0=160,r1=260){const G=qvGraph();const out=[];for(let k=0;k<n;k++){let p=null;for(let t=0;t<12&&!p;t++){const a=(at&&at.a!=null?at.a:Math.random()*6.28)+(Math.random()-.5)*1.6,d=r0+Math.random()*(r1-r0),cx=(at?at.x:RO.x)+Math.sin(a)*d,cz=(at?at.z:RO.z)+Math.cos(a)*d,i=qvNear(cx,cz,200);if(i>=0&&Math.hypot(G.X[i]-RO.x,G.Z[i]-RO.z)>60&&!M1.goons.some(q=>!q.dead&&Math.hypot(q.x-G.X[i],q.z-G.Z[i])<14))p={x:G.X[i],z:G.Z[i]}}if(!p)p={x:RO.x+Math.sin(k)*r0,z:RO.z+Math.cos(k)*r0};out.push(M1_goon(kind,p.x,p.z,{S}))}return out}
function M1_hitGoon(g,dmg,why){if(g.dead)return;g.hp-=dmg;const at=g.m.position.clone().add(V3(0,2,0));debris(at,V3(0,6,0),7,[new THREE.Color('#18181d'),new THREE.Color('#ffd12c')],.5,at.y-2);M1_snd('crash');shake=Math.max(shake,.45);if(g.hp<=0)return M1_takedown(g);g.stall=.7;if(g.kind==='thief'){g.bst=2;g.inv=3}else if(g.kind==='lt'){g.bst=2.4}else if(g.hp===1&&g.kind==='rammer'){g.st='flee';g.ft=2.6}hitPop((why||'💥 HIT')+` · ${g.hp}/${g.hp0}`,'#ffd400')}
function M1_takedown(g){g.dead=1;g.dt=0;g.vy=8;g.spin=(Math.random()-.5)*9;const at=g.m.position.clone().add(V3(0,2,0));debris(at,V3(Math.sin(RO.h)*12,7,Math.cos(RO.h)*12),12,[new THREE.Color('#18181d'),new THREE.Color('#ffd12c'),new THREE.Color('#ff2d55')],.6,at.y-2);burst(FIRE,at,camera.position.distanceTo(at)<14?6:16,20,.6,new THREE.Color(1.6,.8,.25));for(let k=0;k<3;k++)studBurst(at,V3(Math.sin(g.h),0,Math.cos(g.h)),36);
  M1_snd('takedown');slowmo=Math.max(slowmo,.45);fovKick=Math.max(fovKick,12);shake=.5;hitPop(g.kind==='thief'?'🚨 GOT HIM!':'💥 TAKEDOWN!','#5dffb0');studGain(120,1);M1.log.td++;M1.hp=Math.min(100,M1.hp+10);if(M1.tok===g.id)M1.tokT=0;M1.tdc={x:g.x,z:g.z,t:.9};if(g.S)g.S.kill=(g.S.kill||0)+1;const ch=RO.ch;if(ch&&ch.v2&&ch.v2.L.st[ch.v2.si]&&ch.v2.L.st[ch.v2.si].bonus)ch.v2.left+=ch.v2.L.st[ch.v2.si].bonus}
