  if(S.t==='follow'||S.t==='tail'){const pts=S.t==='follow'?S.pts:[{x:RO.x+Math.sin(RO.h)*70,z:RO.z+Math.cos(RO.h)*70},...(S.via||[]),S.to];const R=M1_path(pts.map(p=>M1_P(p.x,p.z)));S.R=R;S.s=0;S.cv=0;S.away=0;S.m=S.t==='follow'?M1_hilde():(M1.kaiser&&M1.kaiser.parent?M1.kaiser:M1_obj({m:M1_car('sedan-sports','#101014',3,'#ffd12c')}).m);if(S.t==='tail')M1.kaiser=S.m;const a=qvAt(R.P,R.C,S.t==='follow'?40:0);M1_put(S.m,a.x,a.z,a.h);S.vx=a.x;S.vz=a.z;if(S.t==='follow'){S.s=S.s0=40;FX19_side(S,a);const p0=qvAt(R.P,R.C,0);M1_warp(p0.x,p0.z,p0.h);S.h0=p0.h}}
  else if(S.t==='thieves'){S.th=[];const from0=S.split&&ch.vanAt?ch.vanAt:null,a0=Math.random()*6.28;S.list.forEach((q,k)=>{const f=from0||q.from||{x:RO.x,z:RO.z};let to=q.to,P=null;{const G=qvGraph();for(let tr=0;tr<14;tr++){if(tr>0||from0){const an=a0+k*2.09+(tr?(tr%2?1:-1)*Math.ceil(tr/2)*.35:0),r=[1100,900,1300,700][tr%4],i=qvNear(f.x+Math.sin(an)*r,f.z+Math.cos(an)*r,300);if(i<0)continue;to={x:G.X[i],z:G.Z[i]}}const Q=qvPath(f.x,f.z,to.x,to.z),Cq=qvCum(Q);if(Q.length>2&&Cq[Cq.length-1]>=650){P=Q;break}if(!P||Cq[Cq.length-1]>qvCum(P).slice(-1)[0])P=Q}}const Cp=qvCum(P),s0=Math.min(k*14,Cp[Cp.length-1]*.5),a0p=qvAt(P,Cp,s0);const g=M1_goon('thief',a0p.x,a0p.z,{S,hp:q.rams,P,drop:q.drop});g.C=Cp;g.s=s0;{const Cg=qvCum(P);if(Cg[Cg.length-1]<650)g.noEsc=1}S.th.push(g)});if(S.split){slowmo=Math.max(slowmo,.5);say('SPLIT!','THREE VANS · RAM THEM ALL',1.8)}}
  else if(S.t==='booths'){S.it=S.items.map(([x,z,h])=>{const g=new THREE.Group(),Mb=new THREE.MeshStandardMaterial({color:0x22232a,roughness:.6}),Mg=new THREE.MeshStandardMaterial({color:0xffd12c,roughness:.5,emissive:new THREE.Color('#5a4300')});box(g,Mb,5,5,4,0,2.5,0);box(g,Mg,5.4,.8,4.4,0,5.4,0);box(g,Mg,9,.6,.6,5,2.6,0);g.position.set(x,groundAt(x,z,40),z);g.rotation.y=h;RO.grp.add(g);M1_obj({m:g});return{x,z,m:g,done:false}});S.n=0;S.x=S.it[0].x;S.z=S.it[0].z;M1_spawn(S,'rammer',S.guards||0,{x:S.x,z:S.z},90,160)}
  else if(S.t==='goons'){S.kill=0;for(const[k,n]of S.wave){const at=S.at==='romer'?M1_L('romer'):null;M1_spawn(S,k,n,at,at?40:150,at?120:240)}say(S.wave.some(w=>w[0]==='lt')?'LIEUTENANT!':'GOONS!',S.txt.toUpperCase(),1.6)}
  else if(S.t==='survive'){S.el=0;S.kill=0;S.spT=0;S.bossOn=0;const at=S.at==='romer'?M1_L('romer'):null;M1_spawn(S,'rammer',Math.min(2,S.max),at,at?50:150,at?130:230);say('GOONS!',S.txt.toUpperCase(),1.6)}
  else if(S.t==='driftzone'){S.n=0;S.el=0}
  else if(S.t==='tower'){const g=new THREE.Group();for(let k=0;k<6;k++){const M=vmat(TEAMS[k%TEAMS.length]);box(g,M.a,7-k*.6,3,7-k*.6,0,1.5+k*3,0)}g.position.set(S.x,groundY(S.x,S.z),S.z);RO.grp.add(g);M1_obj({m:g});S.m=g;S.hp0=S.hp;S.cd=0}
  else if(S.t==='jumpR'&&S.steg&&RO.marks.some(q=>q.kind==='otg'&&q.ev.id==='lj1'&&q.rampAt)){const m=RO.marks.find(q=>q.kind==='otg'&&q.ev.id==='lj1'&&q.rampAt),r=m.rampAt;S.r=r;S.rh=r.h;let ax=m.x,az=m.z;const dx=ax-r.x,dz=az-r.z,dd=Math.hypot(dx,dz)||1;for(const L of[120,100,80]){const x=r.x+dx/dd*L,z=r.z+dz/dd*L;let ok=true;for(let k=10;k<L;k+=6)if(roamHit(r.x+dx/dd*k,r.z+dz/dd*k,2.5,deckY(M1_bridge('steg')||{half:0},0)||0)){ok=false;break}if(ok){ax=x;az=z;break}}S.x=S.ax=ax;S.z=S.az=az;S.rh=Math.atan2(r.x-ax,r.z-az);const b=M1_bridge('steg');if(b){for(const sd of[-1,1]){const[x,z]=deckPt(b,sd*30);const pn=new THREE.Mesh(new THREE.BoxGeometry(b.w,1.2,16),new THREE.MeshStandardMaterial({color:0x6b6f78,roughness:.6}));pn.position.set(x,deckY(b,sd*30)+4,z);pn.rotation.set(-sd*.35,Math.atan2(b.ux,b.uz),0,'YXZ');RO.grp.add(pn);M1_obj({m:pn})}}}
